import math

def tau(n):
    if n <= 0:
        return 0
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def d(n):
    if n == 1:
        # Divisors of 1 are {1}. Divisors other than 1 and itself is an empty set.
        return 0
    # d(n) = tau(n) - 2 (excluding 1 and n itself)
    return tau(n) - 2

# We search for the smallest a = d(n) such that d(n) = d(n + 735)
# We search n starting from 1.
search_limit = 1000
results = []

for n in range(1, search_limit + 1):
    dn = d(n)
    dn_plus_735 = d(n + 735)

    if dn == dn_plus_735:
        results.append((n, dn))

if not results:
    print("No match found up to n = 1000.")
else:
    # The least non-negative integer a is the minimum dn found
    min_a = min(a for n, a in results)
    print(f"Matches found: {results}")
    print(f"The least non-negative integer a is: {min_a}")

def count_divisors(n):
    # D(n) is the number of all divisors.
    # d(n) is the number of divisors other than 1 and n.
    # d(n) = D(n) - 2 if n > 1, and d(1) = 0.
    if n == 1:
        return 0
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            count += 1
            if i*i != n:
                count += 1
    return count - 2

def find_n(a, limit):
    for n in range(1, limit):
        if count_divisors(n) == a and count_divisors(n + 735) == a:
            return n
    return None

print(f"a=0: {find_n(0, 10000)}")
print(f"a=1: {find_n(1, 10000)}")
print(f"a=2: {find_n(2, 100000)}")

